TYPE GateState : (IDLE, OPENING, CLOSING, FAULT);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state           : GateState := IDLE;
    prevOpenBtn     : BOOL := FALSE;
    prevCloseBtn    : BOOL := FALSE;
    openBtnRising   : BOOL;
    closeBtnRising  : BOOL;
END_VAR

    // Rising‑edge detection
    openBtnRising  := openBtn  AND NOT prevOpenBtn;
    closeBtnRising := closeBtn AND NOT prevCloseBtn;

    // State machine
    CASE state OF
        IDLE:
            motorUp   := FALSE;
            motorDown := FALSE;
            IF openBtnRising AND NOT openLimit THEN
                state := OPENING;
            ELSIF closeBtnRising AND NOT closeLimit THEN
                state := CLOSING;
            END_IF

        OPENING:
            motorUp   := TRUE;
            motorDown := FALSE;
            IF obstacle THEN
                motorUp   := FALSE;
                errorFlag := TRUE;
                state     := FAULT;
            ELSIF openLimit THEN
                motorUp   := FALSE;
                state     := IDLE;
            END_IF

        CLOSING:
            motorUp   := FALSE;
            motorDown := TRUE;
            IF obstacle THEN
                motorDown := FALSE;
                motorUp   := TRUE;
                state     := OPENING;
            ELSIF closeLimit THEN
                motorDown := FALSE;
                state     := IDLE;
            END_IF

        FAULT:
            motorUp   := FALSE;
            motorDown := FALSE;
            errorFlag := TRUE;
            // Reset only on simultaneous rising edges of both buttons when obstacle is cleared
            IF openBtnRising AND closeBtnRising AND NOT obstacle THEN
                errorFlag := FALSE;
                state     := IDLE;
            END_IF
    END_CASE

    // Store button states for next scan
    prevOpenBtn  := openBtn;
    prevCloseBtn := closeBtn;

END_FUNCTION_BLOCK
